import { useState } from 'react';
import Card from 'react-bootstrap/Card';
import Button from 'react-bootstrap/Button';
import Modal from 'react-bootstrap/Modal';

function ServiceCard({ title, description, imgSrc,imgSrcs, secretary, doctor, workHours }) {
  const [show, setShow] = useState(false);

  const handleClose = () => setShow(false);
  const handleShow = () => setShow(true);

  return (
    <>
      <Card
        style={{
          width: '18rem',
          borderRadius: '12px',
          boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
          overflow: 'hidden',
          transition: 'transform 0.3s ease-in-out',
        }}
        onMouseEnter={(e) => (e.currentTarget.style.transform = 'scale(1.05)')}
        onMouseLeave={(e) => (e.currentTarget.style.transform = 'scale(1)')}
      >
        <div style={{ display: 'flex', justifyContent: 'center', paddingTop: '15px', marginBottom: '5px' }}>
          <Card.Img variant="top" src={require(`../Images/Icons/${imgSrc}`)} style={{ width: '80px' }} alt={title}/>
        </div>
        <Card.Body style={{ textAlign: 'center', padding: '15px' }}>
          <Card.Title style={{ fontWeight: 'bold', fontSize: '1.2rem' }}>{title}</Card.Title>
          <Card.Text style={{ fontSize: '0.9rem', color: '#555' }}>{description}</Card.Text>
          <Button variant="primary" style={{ width: '100%', borderRadius: '8px' }} onClick={handleShow}>
            Learn More
          </Button>
        </Card.Body>
      </Card>

      {/* Modal */}
      <Modal show={show} onHide={handleClose} centered>
        <Modal.Header closeButton>
          <Modal.Title>{title}</Modal.Title>
        </Modal.Header>
        <Modal.Body style={{ textAlign: 'center' }}>
          {/* Image de service */}
          <img 
            src={require(`../Images/Icons/${imgSrcs}`)} 
            alt={title} 
            style={{ width: '320px', height: '320px', borderRadius: '12px', marginBottom: '10px' }} 
          />
          {/* Informations du service */}
          <p><strong>Description:</strong> {description}</p>
          <p><strong>Secrétaire:</strong> {secretary}</p>
          <p><strong>Docteur en charge:</strong> {doctor}</p>
          <p><strong>Heures de travail:</strong> {workHours}</p>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={handleClose}>
            Fermer
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
}

export default ServiceCard;
