import React, { useEffect } from 'react';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import './map-style.css';

const CarteInteractive = () => {
  useEffect(() => {
    // Initialisation de la carte avec un zoom plus fluide
    const map = L.map('map', {
      zoomControl: false,
      scrollWheelZoom: false
    }).setView([36.365, 6.614], 13); // Coordonnées de Constantine, Algérie

    // Ajout d'un contrôle de zoom personnalisé
    L.control.zoom({
      position: 'topright'
    }).addTo(map);

    // Ajout de la couche de tuiles (OpenStreetMap)
    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}.png', {
      maxZoom: 18,
      attribution: '© CartoDB'
    }).addTo(map);

    // Marqueur avec animation de rebond
    const markerIcon = L.icon({
      iconUrl: 'https://cdn-icons-png.flaticon.com/512/684/684908.png',
      iconSize: [40, 40],
      iconAnchor: [20, 40],
      popupAnchor: [0, -40]
    });

    const marker = L.marker([36.365, 6.614], { icon: markerIcon }).addTo(map);
    marker.bindPopup("<b>Notre Emplacement</b><br>03 Rue Mohamed Sadek, Constantine").openPopup();

    // Animation de rebond sur le marqueur
    marker.on('mouseover', function () {
      marker.setBounceOptions({
        bounceHeight: 20,
        contractHeight: 10,
        bounceSpeed: 54
      }).bounce();
    });
  }, []);

  return (
<section className="carte-container">
  <h2>📍 Notre Emplacement</h2>
  <div id="map"></div>
</section>

  );
};

export default CarteInteractive;
