import React, { useState, useEffect } from 'react'; // Import useState hook
import MasonryGrid from "./MasonryGrid";
import "./home.css";
import { Swiper, SwiperSlide } from 'swiper/react';
import 'swiper/css';
import 'swiper/css/navigation';
import AOS from 'aos';
import 'aos/dist/aos.css';
import { Navigation, Autoplay } from 'swiper/modules';
import Doctors from '../Doctors/Doctors';
import Services from '../modal/Services';
const ServiceBox = ({ icon, text }) => (
  <div className="service-box">
    <div className="service-icon">{icon}</div>
    <div className="service-text">{text}</div>
  </div>
);


function Home() {
  // State to store the email input value
  const [email, setEmail] = useState('');

  // Handle input changes
  const handleChange = (e) => {
    setEmail(e.target.value);
  };

  // Handle form submission
  const handleSubmit = (event) => {
    event.preventDefault(); // Prevents the default form submission
    alert('Email submitted: ' + email);

    // You can add your email subscription logic here, like an API call.
    // After submission, you may want to clear the email input
    setEmail('');
  };

  
  useEffect(() => {
    function disableAOSOnSmallScreens() {
      const elements = document.querySelectorAll("[data-aos]");
      
      if (window.innerWidth < 768) {
        elements.forEach(el => el.removeAttribute("data-aos"));
      } else {
        AOS.init({
          duration: 1000,
          easing: "ease-in-out",
        });
      }
    }

    disableAOSOnSmallScreens(); // Exécute la fonction immédiatement
    window.addEventListener("resize", disableAOSOnSmallScreens); // Surveille le resize

    return () => {
      window.removeEventListener("resize", disableAOSOnSmallScreens); // Nettoie l'event listener
    };
  }, []);


  const [name, setName] = useState('');
  const [mail, setMail] = useState('');
  const [service, setService] = useState('');
  const [message, setMessage] = useState('');
   /* const [formdata, setFormdata] = useState({name: ""}, {email:""}, {service:""}, {message:""});

    const handling= (change) => {
      setFormdata({ ...formdata, [change.target.name]: change.target.value });
    };*/

 function handleChanges  (input)  {
    const { name, value } = input.target;

    if (name === 'name') {
      setName(value);
    } else if (name === 'email') {
      setMail(value);
    } else if (name === 'service') {
      setService(value);  // Ensure the service state is updated correctly
    } else if (name === 'message') {
      setMessage(value);
    }
  };

  function handleSubmits(a) {
    a.preventDefault(); // Empêche l'envoi par défaut

    if (!name || !mail || !service) {
        alert('Please fill in all required fields');
    } else {
        // Créer l'objet contenant les données du formulaire
        const formData = {
            name,
            mail,
            service,
            message
        };

        // Envoyer les données vers Laravel via fetch
        fetch('http://127.0.0.1:8000/api/appointments', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json'
            },
            body: JSON.stringify(formData)
        })
        .then(response => response.json())
        .then(data => {
            alert(`Appointment booked successfully!\n${JSON.stringify(data)}`);
            
            // Réinitialiser les champs du formulaire après succès
            setName('');
            setMail('');
            setService('');
            setMessage('');
        })
        .catch(error => {
            console.error('Error:', error);
            alert('An error occurred while booking the appointment.');
        });
    }
};

  return <>
 <main className="main-container">
      <Swiper
        className="mySwiper"
        navigation={{
          nextEl: '.swiper-button-next',
          prevEl: '.swiper-button-prev',
        }}
        modules={[Navigation, Autoplay]}
        loop={true}
        autoplay={{
          delay: 3000,
          disableOnInteraction: false,
        }}
        pagination={{ clickable: true }}
        effect="fade"
        fadeEffect={{ crossFade: true }}
      >
        <SwiperSlide className="slide1">
          <div className="placement">
            <div className="slogan text-center">
              <h1 className="display-4 text-uppercase animate__animated animate__fadeInDown">
                Soins Adéquats pour Tous
              </h1>
              <h2 className="text-light fs-4 animate__animated animate__fadeInUp">
                Découvrez nos services d'exception
              </h2>
              <button className="btn btn-primary mt-3">
                <i className="fas fa-info-circle me-2"></i> En savoir plus
              </button>
            </div>
          </div>
        </SwiperSlide>

        <SwiperSlide className="slide2">
          <div className="placement">
            <div className="slogan text-center">
              <h1 id="slideh1" className="display-4 text-uppercase animate__animated animate__fadeInDown">
              Soins d'excellence, bien-être au cœur.
              </h1>
              <h2 className="text-light fs-4 animate__animated animate__fadeInUp">
                Confiance et qualité pour votre santé
              </h2>
              <button className="btn btn-success mt-3">
                <i className="fas fa-heart me-2"></i> Découvrir
              </button>
            </div>
          </div>
        </SwiperSlide>

        <SwiperSlide className="slide3">
          <div className="placement">
            <div className="slogan text-center">
              <h1 className="display-4 text-uppercase animate__animated animate__fadeInDown">
              Une équipe professionnel à vos côtés.
              </h1>
              <h2 className="text-light fs-4 animate__animated animate__fadeInUp">
              Engagement et bienveillance chaque jour.
              </h2>
              <button className="btn btn-info mt-3">
                <i className="fas fa-phone me-2"></i> Contactez-nous
              </button>
            </div>
          </div>
        </SwiperSlide>
        
        <div className="swiper-button-next" aria-label="Suivant"></div>
        <div className="swiper-button-prev" aria-label="Précédent"></div>
      </Swiper>
    </main>

    <section className="about">
    <div className="title_homewhy" >
  <h1 style={{ color: "#2D3142", borderBottom: "2px solid #F4D160", display: "inline-block", paddingBottom: "5px" }}>
    PourQuoi nous choisir ?
  </h1>
  <p style={{ color: "#6B9AC4" }}>
        Toute vos Besoin, Chaque details qui vous conserne nous importe
  </p>
</div>

      <div className="about-container">
        <div className="about-box">
          <div
            className="about-img"
            data-aos="fade-left"
            data-aos-offset="300"

          >
            <img src={require('../Images/image6.jpg')} alt="Luxury" />
          </div>
          <div
            className="about-text"
            data-aos="fade-right"
            data-aos-offset="300"

          >
<h3>Des Experts Dévoués à Votre Vie</h3>
<p>
  Chaque intervention est plus qu'une mission : c'est un engagement. Notre équipe de chirurgiens expérimentés veille sur vous avec précision, humanité et un dévouement sans faille. Votre vie est entre de bonnes mains.
</p>
          </div>
        </div>




        <div className="about-box">
          <div
            className="about-img"
            data-aos="fade-left"
            data-aos-offset="300"

          >
            <img src={require('../Images/image7.jpg')} alt="Advanced" />
          </div>
          <div
            className="about-text"
            data-aos="fade-right"
            data-aos-offset="300"

          >
<h3>Une Équipe de Chirurgiens d'Excellence</h3>
<p>
  Votre santé est notre priorité absolue. Avec des chirurgiens hautement qualifiés et expérimentés, vous êtes entre des mains expertes pour chaque étape de votre parcours médical.
</p>
          </div>
        </div>




 

        <div className="about-box">
          <div
            className="about-img"
            data-aos="fade-left"
            data-aos-offset="300"
          >
            <img src={require('../Images/image8.jpg')} alt="Resort" loading='lazy'/>
          </div>
          <div
            className="about-text"
            data-aos="fade-right"
            data-aos-offset="300"

          >
          <h3>Soins Personnalisés</h3>
<p>
  Que ce soit pour une consultation ou un traitement rapide, nous mettons tout en œuvre pour faire de votre expérience un moment rassurant et bienveillant.
</p>
          </div>
        </div>
      </div>
  
    </section>



    <Doctors />






{/*  card section  */}


<Services />


{ /* end of card section */}

    <div className="home_container">
      <div className="left">
      <ServiceBox icon="🩺" text="General Consultation" />
<ServiceBox icon="🔍" text="Radio Consultation" />
<ServiceBox icon="💉" text="Vaccination" />
<ServiceBox icon="🩹" text="Minor Surgery" />
      </div>
      <div className="right">
      <form onSubmit={handleSubmits} method={'POST'}>
      <div className="form-group">
        <label htmlFor="name">Name</label>
        <input
          type="text"
          id="name"
          name="name"
          value={name}
          onChange={handleChanges}
          required
        />
      </div>

      <div className="form-group">
        <label htmlFor="email">Email</label>
        <input
          type="email"
          id="email"
          name="email"
          value={mail}
          onChange={handleChanges}
          required
        />
      </div>

      <div className="form-group">
        <label htmlFor="service">Select Service</label>
        <select
          id="service"
          name="service"
          value={service}  // Make sure the 'value' is bound to the state
          onChange={handleChanges}  // Ensure onChange is updating the state
          required
        >
          <option value="">Please select a service</option>
          <option value="consultation">General Consultation</option>
          <option value="vaccination">Vaccination</option>
          <option value="radio-analyses">Radio Analyses</option>
          <option value="minor-surgery">Minor Surgery</option>
        </select>
      </div>

      <div className="form-group">
        <label htmlFor="message">Message</label>
        <textarea
          id="message"
          name="message"
          rows="4"
          value={message}
          onChange={handleChanges}
        ></textarea>
      </div>

      <input type="submit" value="Book Appointment" />
    </form>
      </div>
    </div>

    <div className="container_letter">
    <div className="title_homewhy" >
  <h1 style={{ color: "#2D3142", borderBottom: "2px solid #F4D160", display: "inline-block", paddingBottom: "5px" }}>
    Notre Gallerie
  </h1>
  <p style={{ color: "#6B9AC4" }}>
       Un centre professionell , une propreté sans egal
  </p>
</div>
</div>

    

<MasonryGrid />



    <div className="newsletter">
      <div className="container_letter">
        <h1 id="HeadText" className="animate__animated animate__backInUp">
          Subscribe to our newsletter
        </h1>
        <h3 >Subscribe to our NewsLetter and stay updated.</h3>
        <form onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder="Enter Your Email"
            value={email} // Bind input value to state
            onChange={handleChange} // Update state on input change
            required
          />
          <button type="submit">Subscribe</button>
        </form>
      </div>
    </div>


  </>;
}

export default Home;
