import React, { useState, useEffect } from "react";
import "./MasonryGrid.css"; // Import the custom CSS

// Array of image paths and optional captions
const images = [
  { src: require("../Images/grid gallery/img1.jpg"), alt: "Our center", caption: "Our Center" },
  { src: require("../Images/grid gallery/img2.jpg"), alt: "chambre analyse", caption: "Chambre Analyse" },
  { src: require("../Images/grid gallery/img3.jpg"), alt: "Acceuil", caption: "Salle d'atentte Acceuil" },
  { src: require("../Images/grid gallery/img4.jpg"), alt: "Image 4", caption: "Caption for Image 4" },
  { src: require("../Images/grid gallery/img5.jpg"), alt: "Image 5", caption: "Caption for Image 5" },
  { src: require("../Images/grid gallery/img6.jpg"), alt: "Image 6", caption: "Caption for Image 6" },
  { src: require("../Images/grid gallery/img7.jpg"), alt: "Image 7", caption: "Caption for Image 7" },
  { src: require("../Images/grid gallery/img9.jpg"), alt: "Image 6", caption: "Caption for Image 8" },
  { src: require("../Images/grid gallery/img8.jpg"), alt: "v", caption: "Rest Room for our patient" },
];

const MasonryGrid = () => {
  const [loadedImages, setLoadedImages] = useState([]);

  // Simulate lazy loading with a delay
  useEffect(() => {
    const loadImages = async () => {
      const loaded = await Promise.all(
        images.map((image) => {
          return new Promise((resolve) => {
            const img = new Image();
            img.src = image.src;
            img.onload = () => resolve({ ...image, loaded: true });
          });
        })
      );
      setLoadedImages(loaded);
    };

    loadImages();
  }, []);

  return (
    <div className="masonry-container">
      {loadedImages.map((image, index) => (
        <div className="masonry-item" key={index}>
          <img
            src={image.src}
            alt={image.alt}
            className={image.loaded ? "loaded" : ""} // Add class for fade-in effect
            loading="lazy" // Enable native lazy loading
          />
          {image.caption && (
            <figcaption className="masonry-caption" >{image.caption}</figcaption>
          )}
        </div>
      ))}
    </div>
  );
};

export default MasonryGrid;