import React from "react";
import "./servicesstyle.css";
import Avaibleservices from '../../modal/Allservices';
import { motion } from "framer-motion";

const Services = () => {
    return (
        <>
        <main className="main_services">
            <div className="placement3">
                <div className="slogan text-center">
                    <motion.h1 
                        id="slideh1"
                        className="display-4 text-uppercase"
                        initial={{ opacity: 0, y: -50 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 0.8, ease: "easeOut" }}
                    >
                        Une Large Gamme De Services
                    </motion.h1>
                    <motion.h2 
                        className="text-light fs-4"
                        initial={{ opacity: 0, y: 50 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ duration: 1, ease: "easeOut", delay: 0.2 }}
                    >
                        Pour tous vos besoins et votre bien-être.
                    </motion.h2>
                </div>
            </div>
        </main>

        {/* Start of services content */}
        <motion.div
            initial="hidden"
            animate="visible"
            variants={{
                hidden: { opacity: 0, scale: 0.9 },
                visible: { 
                    opacity: 1, 
                    scale: 1, 
                    transition: { 
                        duration: 1, 
                        ease: "easeOut",
                        staggerChildren: 0.3, // Animation progressive des enfants
                    } 
                }
            }}
        >
            <motion.div 
           
            >
                <Avaibleservices />
            </motion.div>
        </motion.div>
        {/* End of services */}
        
        </>
    );
};

export default Services;
